mapper.select:
SELECT  FROM workflow_step
WHERE campaign_id = #{campaignId}
ORDER BY step_id

mapper.update:
UPDATE workflow_step SET next_step_id = #{nextStepId}, yes_step_id = #{yesStepId},
	no_step_id = #{noStepId}, updated_at = now()
WHERE step_id = #{stepId}

UPDATE workflow_step AS w SET next_step_id = v.next_id, yes_step_id = v.yes_id, no_step_id = v.no_id, updated_at = now() FROM (VALUES
(CAST(#{item.stepId} AS bigint), CAST(#{item.nextStepId,jdbcType=BIGINT} AS bigint), CAST(#{item.yesStepId,jdbcType=BIGINT} AS bigint), CAST(#{item.noStepId,jdbcType=BIGINT} AS bigint))
) AS v(step_id, next_id, yes_id, no_id) WHERE w.step_id = v.step_id
